('5a4e0011-0000-4000-8000-000000002658', '5a4e0010-0000-4000-8000-000000000470', '5a4e0000-0000-4000-8000-000000040007', 'Merhaba, 22.08 tarihinde Ankara''de konferans organizasyonumuz var. Yaklaşık 30 kişi bekliyoruz. Müsait misiniz, fiyat bilgisi alabilir miyim?', 'text', NULL, pg_temp.t(1831.20), pg_temp.t(1826.85)),
('5a4e0011-0000-4000-8000-000000002659', '5a4e0010-0000-4000-8000-000000000470', '5a4e0000-0000-4000-8000-000000010107', 'Merhaba! Takvimde 22.08 boş görünüyor. Birkaç soru: etkinlik kaç saat sürecek, mekan açık mı kapalı mı? Ardından teklifi iletirim.', 'text', NULL, pg_temp.t(1830.35), pg_temp.t(1807.85)),
('5a4e0011-0000-4000-8000-000000002660', '5a4e0010-0000-4000-8000-000000000470', '5a4e0000-0000-4000-8000-000000040007', 'Açık hava, Etimesgut. Yağmur planı için alternatif de var. Ekibiniz kaç kişi geliyor?', 'text', NULL, pg_temp.t(1817.98), pg_temp.t(1814.24)),
